import React, { useState } from "react";
import {
  Box,
  Button,
  Grid,
  TextField,
  MenuItem,
  Typography,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
} from "@mui/material";
import toastMessage from "../../utils/toastMessage";
import {
  verifyBankAccount,
  B2BBankTransfer,
  searchBeneficiaryByMobile,
} from "../../api/login/Login";

const TRANSFER_MODES = [
  "IMPS",
  "NEFT",
  "RTGS",
  "BANKTRANSFER",
];

const ACCOUNT_TYPES = ["SAVINGS", "CURRENT"];

const B2BBankTransferPage = () => {
  const [verified, setVerified] = useState(false);
  const [searchMobile, setSearchMobile] = useState("");
const [savedBeneficiaries, setSavedBeneficiaries] = useState([]);
const [searchLoading, setSearchLoading] = useState(false);
  const [skipVerify, setSkipVerify] = useState(false);
  const [loading, setLoading] = useState(false);
  const [openTpin, setOpenTpin] = useState(false);
  const [tpin, setTpin] = useState("");

  const [form, setForm] = useState({
    transfer_mode: "",
    bank_account_number: "",
    bank_ifsc: "",
    beneficiary_name: "",
    beneficiary_account_name: "",
    beneficiary_account_type: "",
    beneficiary_email: "",
    beneficiary_mobile: "",
    beneficiary_add: "",
    beneficiary_city: "",
    beneficiary_state: "",
    beneficiary_pin_code: "",
    transfer_amount: "",
  });

  const setField = (key, value) => {
    setForm((prev) => ({ ...prev, [key]: value }));
  };
    // Added by Aman singh
  const handleSearchBeneficiary = async () => {
    if (!searchMobile || searchMobile.length < 10) {
      toastMessage(true, "Enter valid mobile number");
      return;
    }
    try {
      setSearchLoading(true);
      const res = await searchBeneficiaryByMobile(searchMobile);
      if (res?.data?.error === false && res?.data?.data?.length > 0) {
        setSavedBeneficiaries(res.data.data);
        toastMessage(false, "Beneficiaries found");
      } else {
        setSavedBeneficiaries([]);
        toastMessage(true, res?.data?.message || "No beneficiary found");
      }
    } catch (error) {
      setSavedBeneficiaries([]);
      toastMessage(true, error?.response?.data?.message || "Search failed");
    } finally {
      setSearchLoading(false);
    }
  };

  const selectBeneficiary = (beneficiary) => {
    setForm((prev) => ({
      ...prev,
      bank_account_number: beneficiary.bank_account_number || "",
      bank_ifsc: beneficiary.bank_ifsc || "",
      beneficiary_name: beneficiary.bank_account_name || "",
      beneficiary_account_name: beneficiary.bank_name || "",
      beneficiary_mobile: beneficiary.mobile_number || "",
    }));
    setSkipVerify(true);
    setVerified(true);
    toastMessage(false, "Beneficiary details filled");
  };

  const verifyAccount = async () => {
    if (!form.bank_account_number || !form.bank_ifsc) {
      toastMessage(true, "Account number and IFSC are required");
      return;
    }

    try {
      setLoading(true);

      const res = await verifyBankAccount({
        accountNumber: form.bank_account_number,
        bankIfsc: form.bank_ifsc,
      });

      if (res?.data?.success) {
        const data = res?.data?.data;

        if (!data?.name) {
          toastMessage(true, res?.data?.message || "Unable to fetch account holder name");
          return;
        }

        setForm((prev) => ({
          ...prev,
          beneficiary_name: data.name,
          beneficiary_account_name:
            data.ifscDetails?.bankName || data.name || "Bank Account",
        }));

        setVerified(true);
        toastMessage(false, res?.data?.message || "Account Verified Successfully");
      } else {
        toastMessage(true, res?.data?.message || "Verification failed");
      }
    } catch (error) {
      toastMessage(true, error?.response?.data?.message || "Verification error");
    } finally {
      setLoading(false);
    }
  };
  const handleWithoutVerify = () => {
    if (!form.bank_account_number || !form.bank_ifsc) {
      toastMessage(true, "Account number and IFSC are required");
      return;
    }
    setSkipVerify(true);
    setVerified(true);
  };

  const submitPayout = async () => {
    if (!verified) {
      toastMessage(true, "Please verify bank account first");
      return;
    }

    if (
      !["IMPS", "NEFT", "RTGS", "BANKTRANSFER"].includes(
        form.transfer_mode
      )
    ) {
      toastMessage(
        true,
        "transfer_mode must be one of IMPS, NEFT, RTGS, BANKTRANSFER"
      );
      return;
    }

    if (!/^\d{4}$/.test(tpin)) {
      toastMessage(true, "Invalid TPIN");
      return;
    }

    if (!form.transfer_amount || Number(form.transfer_amount) <= 0) {
      toastMessage(true, "Enter valid amount");
      return;
    }

    try {
      setLoading(true);

      const payload = {
        ...form,
        beneficiary_name: form.beneficiary_name || "Bank User",
        beneficiary_account_name: form.beneficiary_account_name || form.beneficiary_name || "Bank Account",
        beneficiary_account_type: form.beneficiary_account_type || "SAVINGS",
        transfer_amount: Number(form.transfer_amount),
        tpin,
      };

      // Remove optional empty string fields so backend Joi validation does not throw "not allowed to be empty"
      Object.keys(payload).forEach((key) => {
        if (payload[key] === "" && key !== "beneficiary_account_name" && key !== "beneficiary_account_type") {
          delete payload[key];
        }
      });

      const res = await B2BBankTransfer(payload);

      if (res?.data?.success) {
        toastMessage(false, res.data.message || "Payout Successful");
        resetForm();
      } else {
        toastMessage(true, res?.data?.message || "Payout Failed");
      }
    } catch (error) {
      toastMessage(true, error?.response?.data?.message || "Server error");
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setVerified(false);
    setSkipVerify(false);
    setOpenTpin(false);
    setTpin("");
    setForm({
      transfer_mode: "",
      bank_account_number: "",
      bank_ifsc: "",
      beneficiary_name: "",
      beneficiary_account_name: "",
      beneficiary_account_type: "",
      beneficiary_email: "",
      beneficiary_mobile: "",
      beneficiary_add: "",
      beneficiary_city: "",
      beneficiary_state: "",
      beneficiary_pin_code: "",
      transfer_amount: "",
    });
  };

  return (
    <>
      <Box p={3} bgcolor="#fff" borderRadius={2}>
        {/* <Typography variant="h6" mb={2}>
          B2B Bank Transfer
        </Typography>

        <Grid container spacing={2}> */}
                <Typography variant="h6" mb={2}>
          B2B Bank Transfer
        </Typography>

        {/* Added by Aman singh - Search saved beneficiary by mobile */}
        <Box mb={3} p={2} bgcolor="#f9fafb" borderRadius={2}>
          <Typography variant="subtitle1" mb={1}>
            Search Saved Beneficiary
          </Typography>
          <Box sx={{ display: "flex", gap: 2, alignItems: "center" }}>
            <TextField
              size="small"
              label="Mobile Number"
              value={searchMobile}
              disabled={searchLoading}
              onChange={(e) => setSearchMobile(e.target.value)}
            />
            <Button
              variant="outlined"
              onClick={handleSearchBeneficiary}
              disabled={searchLoading}
            >
              {searchLoading ? "Searching..." : "Search"}
            </Button>
          </Box>

          {savedBeneficiaries.length > 0 && (
            <Box mt={2}>
              {savedBeneficiaries.map((beni) => (
                <Box
                  key={beni._id}
                  sx={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    p: 1.5,
                    mb: 1,
                    border: "1px solid #e5e7eb",
                    borderRadius: 1,
                  }}
                >
                  <Box>
                    <Typography variant="body2" fontWeight={600}>
                      {beni.bank_account_name}
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                      {beni.bank_name} — {beni.bank_account_number}
                    </Typography>
                  </Box>
                  <Button
                    size="small"
                    variant="contained"
                    onClick={() => selectBeneficiary(beni)}
                  >
                    Use
                  </Button>
                </Box>
              ))}
            </Box>
          )}
        </Box>

        <Grid container spacing={2}>
          <Grid item xs={12} md={4}>
            <TextField
              select
              fullWidth
              className="mui-autofill-fix"
              label="Transfer Mode"
              value={form.transfer_mode}
              disabled={loading}
              onChange={(e) =>
                setField("transfer_mode", e.target.value)
              }
            >
              {TRANSFER_MODES.map((mode) => (
                <MenuItem key={mode} value={mode}>
                  {mode}
                </MenuItem>
              ))}
            </TextField>
          </Grid>

          <Grid item xs={12} md={4}>
            <TextField
              fullWidth
              label="Account Number"
              className="mui-autofill-fix"
              value={form.bank_account_number}
              disabled={verified || loading}
              onChange={(e) =>
                setField("bank_account_number", e.target.value)
              }
            />
          </Grid>

          <Grid item xs={12} md={4}>
            <TextField
              fullWidth
              className="mui-autofill-fix"
              label="IFSC Code"
              value={form.bank_ifsc}
              disabled={verified || loading}
              onChange={(e) =>
                setField("bank_ifsc", e.target.value.toUpperCase())
              }
            />
          </Grid>

          {/* {!verified && (
            <Grid item xs={12}>
              <Button
                variant="outlined"
                onClick={verifyAccount}
                disabled={loading}
              >
                {loading ? "Verifying..." : "Verify Account"}
              </Button>
            </Grid>
          )} */}
          {/* Added by Aman  singh */}
          {!verified && (
            <Grid item xs={12} sx={{ display: "flex", gap: 2 }}>
              <Button
                variant="outlined"
                onClick={verifyAccount}
                disabled={loading}
              >
                {loading ? "Verifying..." : "Verify Account"}
              </Button>

              <Button
                variant="outlined"
                color="warning"
                onClick={handleWithoutVerify}
                disabled={loading}
              >
                Without Verify
              </Button>
            </Grid>
          )}

          {verified && (
            <>
              {/* <Grid item xs={12} md={4}>
                <TextField
                  fullWidth
                  label="Account Holder Name"
                  className="mui-autofill-fix"
                  value={form.beneficiary_name}
                  disabled
                />
                <Typography variant="caption" color="success.main">
                  ✔ Verified
                </Typography>
              </Grid> */}
              {/* Added by Aman singh */}
              <Grid item xs={12} md={4}>
                <TextField
                  fullWidth
                  label="Account Holder Name"
                  className="mui-autofill-fix"
                  value={form.beneficiary_name}
                  disabled={!skipVerify || loading}
                  onChange={(e) => setField("beneficiary_name", e.target.value)}
                />
                <Typography
                  variant="caption"
                  color={skipVerify ? "warning.main" : "success.main"}
                >
                  {skipVerify ? "⚠ Not Verified" : "✔ Verified"}
                </Typography>
              </Grid>

              {/* <Grid item xs={12} md={4}>
                <TextField
                  fullWidth
                  label="Bank Name"
                  className="mui-autofill-fix"
                  value={form.beneficiary_account_name}
                  disabled
                />
              </Grid> */}
              {/* Added by Aman singh */}

<Grid item xs={12} md={4}>
                <TextField
                  fullWidth
                  label="Bank Name"
                  className="mui-autofill-fix"
                  value={form.beneficiary_account_name}
                  disabled={!skipVerify || loading}
                  onChange={(e) => setField("beneficiary_account_name", e.target.value)}
                />
              </Grid>
              {[
                ["beneficiary_email", "Email"],
                ["beneficiary_mobile", "Mobile"],
                ["beneficiary_add", "Address"],
                ["beneficiary_city", "City"],
                ["beneficiary_state", "State"],
                ["beneficiary_pin_code", "PIN Code"],
              ].map(([key, label]) => (
                <Grid item xs={12} md={4} key={key}>
                  <TextField
                    fullWidth
                    className="mui-autofill-fix"
                    label={label}
                    value={form[key]}
                    disabled={loading}
                    onChange={(e) =>
                      setField(key, e.target.value)
                    }
                  />
                </Grid>
              ))}

              <Grid item xs={12} md={4}>
                <TextField
                  select
                  fullWidth
                  label="Account Type"
                  className="mui-autofill-fix"
                  value={form.beneficiary_account_type}
                  disabled={loading}
                  onChange={(e) =>
                    setField(
                      "beneficiary_account_type",
                      e.target.value
                    )
                  }
                >
                  {ACCOUNT_TYPES.map((type) => (
                    <MenuItem key={type} value={type}>
                      {type}
                    </MenuItem>
                  ))}
                </TextField>
              </Grid>

              <Grid item xs={12} md={4}>
                <TextField
                  fullWidth
                  type="number"
                  className="mui-autofill-fix"
                  label="Amount"
                  value={form.transfer_amount}
                  disabled={loading}
                  onChange={(e) =>
                    setField("transfer_amount", e.target.value)
                  }
                />
              </Grid>
            </>
          )}
        </Grid>

        {verified && (
          <Box mt={3}>
            <Button
              variant="contained"
              onClick={() => setOpenTpin(true)}
              disabled={loading || !form.transfer_mode}
            >
              Submit
            </Button>
          </Box>
        )}
      </Box>

      <Dialog open={openTpin} onClose={() => setOpenTpin(false)}>
        <DialogTitle align="center">Enter TPIN</DialogTitle>
        <DialogContent>
          <TextField
            fullWidth
            type="password"
            className="mui-autofill-fix"
            value={tpin}
            disabled={loading}
            inputProps={{ maxLength: 4 }}
            onChange={(e) =>
              /^\d{0,4}$/.test(e.target.value) &&
              setTpin(e.target.value)
            }
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenTpin(false)} disabled={loading}>
            Cancel
          </Button>
          <Button onClick={submitPayout} disabled={loading}>
            {loading ? "Processing..." : "Confirm"}
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default B2BBankTransferPage;
